function Expand-AgyPulsePayload([string]$gz) {
    $clean = ($gz -replace '\s+', '')
    $gzBytes = [Convert]::FromBase64String($clean)
    $msIn = New-Object System.IO.MemoryStream(,$gzBytes)
    $gzStream = New-Object System.IO.Compression.GZipStream($msIn, [System.IO.Compression.CompressionMode]::Decompress)
    $msOut = New-Object System.IO.MemoryStream
    $gzStream.CopyTo($msOut)
    $gzStream.Dispose()
    $msIn.Dispose()
    $jsonText = [System.Text.Encoding]::UTF8.GetString($msOut.ToArray())
    $msOut.Dispose()
    return ($jsonText | ConvertFrom-Json)
}

function Get-BytesSha256([byte[]]$bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hash = $sha.ComputeHash($bytes)
    $sha.Dispose()
    return ([BitConverter]::ToString($hash) -replace '-', '').ToLowerInvariant()
}

function Enable-SystemProxyEnv {
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    } catch {}

    try {
        if (-not [string]::IsNullOrWhiteSpace($env:HTTPS_PROXY) -or -not [string]::IsNullOrWhiteSpace($env:https_proxy)) {
            return
        }
        $regPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings"
        if (-not (Test-Path $regPath)) { return }
        $inet = Get-ItemProperty -Path $regPath -ErrorAction SilentlyContinue
        if ($null -eq $inet) { return }
        $enProp = $inet.PSObject.Properties['ProxyEnable']
        $srvProp = $inet.PSObject.Properties['ProxyServer']
        if ($null -eq $enProp -or $enProp.Value -ne 1 -or $null -eq $srvProp) { return }

        $rawProxy = ([string]$srvProp.Value).Trim()
        if ([string]::IsNullOrWhiteSpace($rawProxy)) { return }

        if ($rawProxy -match 'https=([^;]+)') {
            $rawProxy = $matches[1].Trim()
        } elseif ($rawProxy -match '=([^;]+)') {
            $rawProxy = $matches[1].Trim()
        }
        if ($rawProxy -and $rawProxy -notmatch '^https?://') {
            $rawProxy = "http://$rawProxy"
        }
        if ($rawProxy) {
            if ([string]::IsNullOrWhiteSpace($env:HTTP_PROXY)) { $env:HTTP_PROXY = $rawProxy }
            if ([string]::IsNullOrWhiteSpace($env:HTTPS_PROXY)) { $env:HTTPS_PROXY = $rawProxy }
            Write-Host "  [i] Detected Windows system proxy: $rawProxy" -ForegroundColor DarkGray
        }
    } catch {}
}

function Stop-AgyPulseProcesses {
    $sidecarDataDir = Join-Path $HOME ".gemini\antigravity\sidecar_data\agy-context-ext"
    $hudPidFile = Join-Path $sidecarDataDir "panel\data\hud.pid"
    if (Test-Path $hudPidFile) {
        try {
            $oldHudPid = [int](Get-Content $hudPidFile -ErrorAction Stop).Trim()
            if ($oldHudPid -gt 0 -and $oldHudPid -ne $PID) {
                Stop-Process -Id $oldHudPid -Force -ErrorAction SilentlyContinue
            }
        } catch {}
    }

    $logPath = Join-Path $sidecarDataDir "panel\logs\sidecar.log"
    if (Test-Path $logPath) {
        try {
            $tail = Get-Content $logPath -Tail 12 -ErrorAction Stop
            $portMatch = ($tail | Select-String -Pattern '127\.0\.0\.1:(\d+)' | Select-Object -Last 1)
            if ($portMatch) {
                $port = [int]$portMatch.Matches[0].Groups[1].Value
                $conns = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue
                foreach ($conn in $conns) {
                    $ownerPid = [int]$conn.OwningProcess
                    if ($ownerPid -gt 0 -and $ownerPid -ne $PID) {
                        $proc = Get-Process -Id $ownerPid -ErrorAction SilentlyContinue
                        if ($proc -and $proc.ProcessName -match '^(Antigravity|node)$') {
                            Stop-Process -Id $ownerPid -Force -ErrorAction SilentlyContinue
                        }
                    }
                }
            }
        } catch {}
    }
}

$bundle = Expand-AgyPulsePayload $PayloadGzBase64
$props = $bundle.PSObject.Properties

if ($DryRunVerify) {
    $count = 0
    foreach ($p in $props) {
        $bytes = [Convert]::FromBase64String([string]$p.Value.b64)
        $actual = Get-BytesSha256 $bytes
        if ($actual -ne [string]$p.Value.sha256) {
            throw "Checksum mismatch on $($p.Name)"
        }
        $count++
    }
    Write-Output "AGY_PULSE_VERIFY_OK ($count files)"
    return
}

if ($Uninstall) {
    Write-Host "==> Uninstalling AGY Pulse..." -ForegroundColor Yellow
    Stop-AgyPulseProcesses
    Start-Sleep -Milliseconds 400
    if (Test-Path $TargetDir) {
        Remove-Item -Path $TargetDir -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "  [-] Removed plugin directory: $TargetDir" -ForegroundColor Gray
    } else {
        Write-Host "  [i] Plugin directory not found: $TargetDir" -ForegroundColor DarkGray
    }
    if (-not $KeepData) {
        $sidecarDataDir = Join-Path $HOME ".gemini\antigravity\sidecar_data\agy-context-ext"
        if (Test-Path $sidecarDataDir) {
            Remove-Item -Path $sidecarDataDir -Recurse -Force -ErrorAction SilentlyContinue
            Write-Host "  [-] Removed runtime data: $sidecarDataDir" -ForegroundColor Gray
        }
    } else {
        Write-Host "  [i] Kept user settings/data (-KeepData)" -ForegroundColor DarkGray
    }
    Write-Host "==> AGY Pulse has been uninstalled cleanly." -ForegroundColor Green
    return
}

Write-Host "==> Installing AGY Pulse (v2.0.0)..." -ForegroundColor Cyan

# Step 1: Ensure official agy CLI is installed & backed up against Antigravity NSIS updates
if (-not $SkipAgyCli) {
    Enable-SystemProxyEnv
    $agyExe = Join-Path $env:LOCALAPPDATA "agy\bin\agy.exe"
    $protectedBin = Join-Path $HOME ".gemini\antigravity\sidecar_data\agy-context-ext\panel\data\bin\agy.exe"
    if ((-not (Test-Path $agyExe)) -and (Test-Path $protectedBin)) {
        $agyBinDir = Split-Path -Parent $agyExe
        if (-not (Test-Path $agyBinDir)) { [void](New-Item -ItemType Directory -Path $agyBinDir -Force) }
        Copy-Item -Path $protectedBin -Destination $agyExe -Force -ErrorAction SilentlyContinue
    }
    $agyReady = (Test-Path $agyExe) -or ($null -ne (Get-Command agy -ErrorAction SilentlyContinue))
    if (-not $agyReady) {
        Write-Host "==> Installing official Antigravity CLI (agy) for live quota sync..." -ForegroundColor Yellow
        $tmpInstallPs1 = Join-Path $env:TEMP ("agy-cli-install-" + [Guid]::NewGuid().ToString('N') + ".ps1")
        try {
            $cliScript = Invoke-RestMethod -Uri "https://antigravity.google/cli/install.ps1" -TimeoutSec 45
            [System.IO.File]::WriteAllText($tmpInstallPs1, [string]$cliScript, [System.Text.Encoding]::UTF8)
            $psExe = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
            $proc = Start-Process -FilePath $psExe -ArgumentList @('-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $tmpInstallPs1) -Wait -NoNewWindow -PassThru
            if ($proc.ExitCode -ne 0) {
                Write-Warning "agy CLI installer exited with code $($proc.ExitCode)"
            }
        } catch {
            Write-Warning "Could not auto-install agy CLI: $($_.Exception.Message)"
        } finally {
            if (Test-Path $tmpInstallPs1) {
                Remove-Item -Path $tmpInstallPs1 -Force -ErrorAction SilentlyContinue
            }
        }

        $agyReady = (Test-Path $agyExe) -or ($null -ne (Get-Command agy -ErrorAction SilentlyContinue))
        if (-not $agyReady) {
            Write-Host "  [!] agy CLI is not installed yet (quota display requires it)." -ForegroundColor Yellow
            Write-Host "      Enable your proxy and click Refresh in the HUD (or re-run this installer)." -ForegroundColor Yellow
        }
    }
    if (Test-Path $agyExe) {
        $protParent = Split-Path -Parent $protectedBin
        if (-not (Test-Path $protParent)) { [void](New-Item -ItemType Directory -Path $protParent -Force) }
        Copy-Item -Path $agyExe -Destination $protectedBin -Force -ErrorAction SilentlyContinue
    }
}

# Step 2: Extract plugin files into target directory
Write-Host "==> Extracting plugin files to: $TargetDir" -ForegroundColor Cyan
foreach ($p in $props) {
    $rel = $p.Name -replace '/', '\'
    $dest = Join-Path $TargetDir $rel
    $parent = Split-Path -Parent $dest
    if (-not (Test-Path $parent)) {
        [void](New-Item -ItemType Directory -Path $parent -Force)
    }
    $bytes = [Convert]::FromBase64String([string]$p.Value.b64)
    $actual = Get-BytesSha256 $bytes
    if ($actual -ne [string]$p.Value.sha256) {
        throw "Integrity check failed for $rel"
    }
    [System.IO.File]::WriteAllBytes($dest, $bytes)
    Write-Host "  [+] Extracted $rel ($($bytes.Length) bytes)" -ForegroundColor Gray
}

# Step 3: Reload running HUD / sidecar so Antigravity respawns the updated plugin
Stop-AgyPulseProcesses

Write-Host "==> Done! AGY Pulse v2.0.0 is installed and active." -ForegroundColor Green
